// spec: .qa/e2e/specs/tenders-list.md
// seed: tests/seed.hunter_free.spec.ts
import { test, expect, Page } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_free.json') });

const TECH = 'טכנולוגיה, מוצר, דאטה ומערכות מידע';
const HEALTH = 'בריאות, מדעי החיים וביוטכנולוגיה';
const ALL = 'כל התחומים';

const expectBothSelected = async (page: Page, expectedCount?: string) => {
  const chip = (name: string) => page.getByRole('button', { name, exact: true });
  await expect(chip(TECH)).toHaveAttribute('aria-pressed', 'true');
  await expect(chip(HEALTH)).toHaveAttribute('aria-pressed', 'true');
  await expect(chip(ALL)).toHaveAttribute('aria-pressed', 'false');
  await expect(page.getByRole('checkbox', { name: TECH, exact: true })).toBeChecked();
  await expect(page.getByRole('checkbox', { name: HEALTH, exact: true })).toBeChecked();
  await expect(page.locator('aside input[type="checkbox"]:checked')).toHaveCount(2);
  if (expectedCount) await expect(page.getByText(/^\d+ תוצאות$/)).toHaveText(expectedCount);
};

test.describe('Field chips on /tenders — multi-select, in sync with the sidebar (#9a6100)', () => {
  test('Sidebar checkboxes → chips in sync; kept after direct URL and reload @desktop @prod-safe #9a6100', async ({ page, context }) => {
    // 1. Open /tenders, tick both fields in the sidebar «תחומי התמחות»
    await page.goto('/tenders');
    await expect(page.getByRole('button', { name: ALL, exact: true })).toHaveAttribute('aria-pressed', 'true');
    // Controlled checkbox: state follows the URL update, so click and wait for the result
    await page.getByRole('checkbox', { name: TECH, exact: true }).click();
    await expect(page).toHaveURL(/[?&]fields=technology(&|$)/);
    await expect(page.getByRole('checkbox', { name: TECH, exact: true })).toBeChecked();
    await page.getByRole('checkbox', { name: HEALTH, exact: true }).click();
    await expect.poll(() => (new URL(page.url()).searchParams.get('fields') ?? '').split(',').sort().join(','))
      .toBe('health,technology');
    await expectBothSelected(page);
    const count = await page.getByText(/^\d+ תוצאות$/).innerText();
    const url = page.url();

    // 2. Reload
    await page.reload();
    await expectBothSelected(page, count);

    // 3. Same URL in a new page (direct URL)
    const fresh = await context.newPage();
    await fresh.goto(url);
    await expectBothSelected(fresh, count);
    await fresh.close();
  });
});
